                jQuery('.dt-main-menu #primary > li.dropdown ').on("mouseenter", function() {
                    jQuery('.dt-primary-menu').addClass('open-submenu');
                    if($(this).hasClass('menu-item-4574') || $(this).hasClass('menu-item-6310'))
